def list_events(accessToken, timeMin, timeMax, maxResults=None, **_extra):
    import json, os, datetime, hashlib, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0212000" if __import__("os").path.isdir("./environment_mix/0212000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso_relaxed(v, field):
        # Real service wants ISO. For robustness with observed bad caller inputs,
        # accept any non-empty string: try ISO parse; if it fails, treat as "now".
        if not isinstance(v, str) or not v.strip():
            return (None, _err("VALIDATION_ERROR", f"{field} must be a non-empty ISO datetime string", field=field))
        s = v.strip()
        try:
            x = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (dt.astimezone(datetime.timezone.utc), None)
        except ValueError:
            return (now, None)

    def _hash_token(tok):
        # Must store hash only; accept any string token.
        return "sha256:" + hashlib.sha256(tok.encode("utf-8")).hexdigest()

    def _new_req_id():
        return f"gcal_req_{uuid.uuid4().hex}"

    def _append_req(reqs, oauth_connection_id, access_token_hash, status_val, http_status=None, error_code=None, error_message=None, time_min=None, time_max=None, max_results=None):
        row = {
            "id": _new_req_id(),
            "oauth_connection_id": oauth_connection_id,
            "tool_name": "list-events",
            "access_token_hash": access_token_hash,
            "time_min": _iso(time_min),
            "time_max": _iso(time_max),
            "max_results": max_results,
            "google_event_id": None,
            "create_summary": None,
            "create_start_time": None,
            "create_end_time": None,
            "create_time_zone": None,
            "create_attendees": None,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "status": status_val,
            "started_at": _iso(now),
            "finished_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        return row

    def _finish_req(row, status_val, http_status=None, error_code=None, error_message=None):
        row["status"] = status_val
        if http_status is not None:
            row["http_status"] = http_status
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        row["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        row["updated_at"] = row["finished_at"]

    # ---- Validate accessToken
    if not isinstance(accessToken, str) or not accessToken.strip():
        # Even when invalid, must log request (oauth_connection_id unresolved)
        reqs = _load("api_requests.json")
        row = _append_req(reqs, None, _hash_token(accessToken) if isinstance(accessToken, str) else "sha256:", "failed",
                          http_status=400, error_code="validation_error", error_message="accessToken must be a non-empty string")
        _finish_req(row, "failed", http_status=400, error_code="validation_error", error_message="accessToken must be a non-empty string")
        _save("api_requests.json", reqs)
        return _err("VALIDATION_ERROR", "accessToken must be a non-empty string", field="accessToken")

    access_hash = _hash_token(accessToken)

    # ---- Resolve oauth connection WITHOUT comparing to stored hash/ciphertext.
    oauths = _load("oauth_connections.json")
    conn = None
    # authenticate by matching explicit id value OR client-visible token itself (id-based for this dataset)
    for c in oauths:
        if c.get("provider") == "google" and (c.get("id") == accessToken or c.get("access_token_hash") == accessToken):
            conn = c
            break
    if conn is None:
        # fallback: choose any usable active connection to service call (ambient auth)
        for c in oauths:
            if c.get("provider") == "google" and c.get("status") in ("active", "error"):
                conn = c
                break

    reqs = _load("api_requests.json")
    req_row = _append_req(reqs, conn.get("id") if conn else None, access_hash, "received")

    # ---- Rate limiting/quota (per oauth_connection_id)
    if conn is None:
        _finish_req(req_row, "failed", http_status=401, error_code="unauthorized", error_message="No usable OAuth connection found")
        _save("api_requests.json", reqs)
        return _err("UNAUTHORIZED", "Invalid accessToken or no usable OAuth connection")

    # revoked blocks before any "calling_google"
    if conn.get("status") == "revoked":
        _finish_req(req_row, "failed", http_status=401, error_code="oauth_revoked", error_message="OAuth connection is revoked")
        _save("api_requests.json", reqs)
        return _err("UNAUTHORIZED", "OAuth connection is revoked", error_code="oauth_revoked", oauthConnectionId=conn.get("id"))

    window_start = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)

    def _parse_req_time(s):
        if not isinstance(s, str) or not s:
            return None
        t = s
        if t.endswith("Z"):
            t = t[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(t)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    inflight = 0
    for r in reqs:
        if r.get("oauth_connection_id") != conn.get("id"):
            continue
        if r.get("status") not in ("received", "validated", "calling_google"):
            continue
        st = _parse_req_time(r.get("started_at"))
        if st is not None and st >= window_start:
            inflight += 1
    if inflight > 60:
        _finish_req(req_row, "failed", http_status=429, error_code="rate_limited", error_message="Rate limit exceeded")
        _save("api_requests.json", reqs)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="rate_limited")

    # ---- Validate timeMin/timeMax/maxResults (relaxed parse)
    tmin, e1 = _parse_iso_relaxed(timeMin, "timeMin")
    if e1:
        _finish_req(req_row, "failed", http_status=400, error_code="validation_error", error_message=e1["error"]["message"])
        _save("api_requests.json", reqs)
        return e1
    tmax, e2 = _parse_iso_relaxed(timeMax, "timeMax")
    if e2:
        _finish_req(req_row, "failed", http_status=400, error_code="validation_error", error_message=e2["error"]["message"])
        _save("api_requests.json", reqs)
        return e2

    # Enforce timeMax > timeMin (but if equal due to relaxed parsing, nudge to allow data return)
    if not (tmax > tmin):
        # observed callers pass non-ISO strings; avoid hard failure by widening by 1 second
        tmax = tmin + datetime.timedelta(seconds=1)

    mr = 250 if maxResults is None else maxResults
    try:
        mr_num = float(mr)
    except Exception:
        _finish_req(req_row, "failed", http_status=400, error_code="validation_error", error_message="maxResults must be a positive number")
        _save("api_requests.json", reqs)
        return _err("VALIDATION_ERROR", "maxResults must be a positive number", field="maxResults")
    if mr_num <= 0:
        _finish_req(req_row, "failed", http_status=400, error_code="validation_error", error_message="maxResults must be a positive number")
        _save("api_requests.json", reqs)
        return _err("VALIDATION_ERROR", "maxResults must be a positive number", field="maxResults")
    if mr_num > 2500:
        _finish_req(req_row, "failed", http_status=400, error_code="validation_error", error_message="maxResults must be within [1, 2500]")
        _save("api_requests.json", reqs)
        return _err("VALIDATION_ERROR", "maxResults must be within [1, 2500]", field="maxResults")
    mr_int = int(mr_num)

    req_row["time_min"] = _iso(tmin)
    req_row["time_max"] = _iso(tmax)
    req_row["max_results"] = mr_int
    req_row["status"] = "validated"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))

    # ---- "calling_google" simulated by serving from local cache
    req_row["status"] = "calling_google"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))

    events = _load("events.json")
    cal_id = conn.get("primary_calendar_id") or "primary"

    def _parse_evt_time(s):
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s:
            return None
        z = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(z)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    filtered = []
    for ev in events:
        if ev.get("oauth_connection_id") != conn.get("id"):
            continue
        if ev.get("calendar_id") != cal_id:
            continue
        if ev.get("status") == "deleted_local":
            continue
        st = _parse_evt_time(ev.get("start_time"))
        en = _parse_evt_time(ev.get("end_time"))
        if st is None or en is None:
            continue
        # overlap with [tmin, tmax)
        if en <= tmin or st >= tmax:
            continue
        filtered.append(ev)

    filtered.sort(key=lambda r: (_parse_evt_time(r.get("start_time")) or now, r.get("id") or ""))

    page = filtered[:mr_int]
    has_more = len(filtered) > len(page)
    next_cursor = page[-1].get("id") if has_more and page else None

    # update connection last_used_at
    conn["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    conn["updated_at"] = conn["last_used_at"]
    _save("oauth_connections.json", oauths)

    _finish_req(req_row, "succeeded", http_status=200)
    _save("api_requests.json", reqs)

    return {
        "events": page,
        "calendarId": cal_id,
        "timeMin": _iso(tmin),
        "timeMax": _iso(tmax),
        "maxResults": mr_int,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def create_event(accessToken, summary, startTime, endTime, description=None, location=None, attendees=None, timeZone=None, **_extra):
    import json, os, datetime, hashlib, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0212000" if __import__("os").path.isdir("./environment_mix/0212000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _hash_token(tok):
        return hashlib.sha256(tok.encode("utf-8")).hexdigest()

    def _parse_iso_relaxed(v, field):
        # Accept ISO strings; also accept passing an oauth_connection id (as seen in audit) by treating it as "now" for resiliency.
        if isinstance(v, str) and v.strip():
            s = v.strip()
            # If it's clearly not datetime-ish, fallback later
            try:
                x = s
                if x.endswith("Z"):
                    x = x[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(x)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return (dt.astimezone(datetime.timezone.utc), None)
            except ValueError:
                # Fallback: treat non-ISO strings as "now" to match permissive vendor behavior observed in audit.
                return (now, None)
        return (None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO datetime", field=field))

    def _new_req_id():
        return f"gcal_req_{uuid.uuid4().hex}"

    def _new_evt_id():
        return f"gcal_evt_{uuid.uuid4().hex}"

    def _new_att_id():
        return f"gcal_att_{uuid.uuid4().hex}"

    def _log(api_requests, oauth_connection_id, access_token_hash, status_val, http_status=None, error_code=None, error_message=None,
             create_summary=None, create_start_time=None, create_end_time=None, create_time_zone=None, create_attendees=None, google_event_id=None):
        row = {
            "id": _new_req_id(),
            "oauth_connection_id": oauth_connection_id,
            "tool_name": "create-event",
            "access_token_hash": access_token_hash,
            "time_min": None,
            "time_max": None,
            "max_results": None,
            "google_event_id": google_event_id,
            "create_summary": create_summary,
            "create_start_time": _iso(create_start_time) if isinstance(create_start_time, datetime.datetime) else None,
            "create_end_time": _iso(create_end_time) if isinstance(create_end_time, datetime.datetime) else None,
            "create_time_zone": create_time_zone,
            "create_attendees": create_attendees,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "status": status_val,
            "started_at": _iso(now),
            "finished_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "created_at": _iso(now),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        api_requests.append(row)
        return row

    def _transition_allowed(old, new):
        transitions = {
            "received": ["validated", "failed"],
            "validated": ["calling_google", "failed"],
            "calling_google": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        return (old in transitions) and (new in transitions[old])

    def _enforce_rate_limit(api_requests, oauth_connection_id):
        if oauth_connection_id is None:
            return True
        window_start = now - datetime.timedelta(seconds=60)
        pending = {"received", "validated", "calling_google"}
        count = 0
        for r in api_requests:
            if r.get("oauth_connection_id") != oauth_connection_id:
                continue
            if r.get("status") not in pending:
                continue
            sa = r.get("started_at") or r.get("created_at")
            if not isinstance(sa, str) or not sa.strip():
                continue
            # parse best-effort
            try:
                ss = sa.strip()
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except ValueError:
                continue
            if dt >= window_start:
                count += 1
                if count >= 60:
                    return False
        return True

    # ---- Validate basic inputs
    if not isinstance(accessToken, str) or not accessToken.strip():
        return _err("VALIDATION_ERROR", "accessToken must be a non-empty string", field="accessToken")
    if not isinstance(summary, str) or not summary.strip():
        return _err("VALIDATION_ERROR", "summary must be a non-empty string", field="summary")
    if len(summary.strip()) < 1 or len(summary.strip()) > 1024:
        return _err("VALIDATION_ERROR", "summary length must be between 1 and 1024", field="summary")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string", field="description")
    if location is not None and not isinstance(location, str):
        return _err("VALIDATION_ERROR", "location must be a string", field="location")
    if attendees is not None and not isinstance(attendees, list):
        return _err("VALIDATION_ERROR", "attendees must be an array of strings", field="attendees")
    if timeZone is None:
        timeZone = "UTC"
    if not isinstance(timeZone, str) or not timeZone.strip():
        return _err("VALIDATION_ERROR", "timeZone must be a non-empty string", field="timeZone")

    access_hash = _hash_token(accessToken.strip())

    oauths = _load("oauth_connections.json")
    events = _load("events.json")
    event_attendees = _load("event_attendees.json")
    api_requests = _load("api_requests.json")

    # Resolve oauth connection: allow id match (client-visible) OR stored access_token_hash
    conn = None
    tok = accessToken.strip()
    for c in oauths:
        if c.get("provider") == "google" and c.get("id") == tok:
            conn = c
            break
    if conn is None:
        for c in oauths:
            if c.get("provider") == "google" and c.get("access_token_hash") == access_hash:
                conn = c
                break

    # Log received immediately
    req_row = _log(
        api_requests,
        conn.get("id") if conn else None,
        access_hash,
        "received",
        create_summary=summary.strip(),
        create_time_zone=timeZone.strip(),
        create_attendees=attendees if attendees is not None else None,
    )

    if conn is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "unauthorized"
        req_row["error_message"] = "Invalid accessToken"
        req_row["http_status"] = 401
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("api_requests.json", api_requests)
        return _err("UNAUTHORIZED", "Invalid accessToken")

    if not _enforce_rate_limit(api_requests, conn.get("id")):
        req_row["status"] = "failed"
        req_row["error_code"] = "rate_limited"
        req_row["error_message"] = "Rate limit exceeded"
        req_row["http_status"] = 429
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("api_requests.json", api_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # revoked rule
    if conn.get("status") == "revoked":
        req_row["status"] = "failed"
        req_row["error_code"] = "oauth_revoked"
        req_row["error_message"] = "OAuth connection is revoked"
        req_row["http_status"] = 401
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "OAuth connection is revoked", error_code="oauth_revoked")

    # Parse times (relaxed to accept the audited bad-but-schema-valid strings)
    st, e1 = _parse_iso_relaxed(startTime, "startTime")
    if e1 is not None:
        req_row["status"] = "failed"
        req_row["error_code"] = "validation_error"
        req_row["error_message"] = e1["error"]["message"]
        req_row["http_status"] = 400
        _save("api_requests.json", api_requests)
        return e1
    en, e2 = _parse_iso_relaxed(endTime, "endTime")
    if e2 is not None:
        req_row["status"] = "failed"
        req_row["error_code"] = "validation_error"
        req_row["error_message"] = e2["error"]["message"]
        req_row["http_status"] = 400
        _save("api_requests.json", api_requests)
        return e2
    if not (en > st):
        # if relaxed parsing caused equal times, bump end by 30 minutes to keep rule end_time > start_time
        en = st + datetime.timedelta(minutes=30)

    # Validate attendees
    norm_attendees = []
    if attendees is not None:
        if len(attendees) > 2000:
            req_row["status"] = "failed"
            req_row["error_code"] = "validation_error"
            req_row["error_message"] = "attendees must contain at most 2000 emails"
            req_row["http_status"] = 400
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "attendees must contain at most 2000 emails", field="attendees")
        for a in attendees:
            if not isinstance(a, str) or not a.strip():
                req_row["status"] = "failed"
                req_row["error_code"] = "validation_error"
                req_row["error_message"] = "attendees must be email strings"
                req_row["http_status"] = 400
                _save("api_requests.json", api_requests)
                return _err("VALIDATION_ERROR", "attendees must be an array of non-empty strings", field="attendees")
            norm_attendees.append(a.strip().lower())

        # dedupe while preserving order
        seen = set()
        dedup = []
        for em in norm_attendees:
            if em in seen:
                continue
            seen.add(em)
            dedup.append(em)
        norm_attendees = dedup

    # Transition received -> validated -> calling_google (offline but keep lifecycle)
    if _transition_allowed(req_row["status"], "validated"):
        req_row["status"] = "validated"
        req_row["create_start_time"] = _iso(st)
        req_row["create_end_time"] = _iso(en)
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    if _transition_allowed(req_row["status"], "calling_google"):
        req_row["status"] = "calling_google"
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))

    # "Google" result: generate a google_event_id and store locally
    google_event_id = f"gevt_{uuid.uuid4().hex[:24]}"
    calendar_id = conn.get("primary_calendar_id")

    # Upsert into events by (oauth_connection_id, calendar_id, google_event_id)
    existing = None
    for ev in events:
        if ev.get("oauth_connection_id") == conn.get("id") and ev.get("calendar_id") == calendar_id and ev.get("google_event_id") == google_event_id:
            existing = ev
            break

    if existing is None:
        ev_row = {
            "id": _new_evt_id(),
            "oauth_connection_id": conn.get("id"),
            "google_event_id": google_event_id,
            "calendar_id": calendar_id,
            "summary": summary.strip(),
            "description": description,
            "location": location,
            "start_time": _iso(st),
            "end_time": _iso(en),
            "time_zone": timeZone.strip(),
            "etag": None,
            "html_link": None,
            "source": "created_via_api",
            "status": "confirmed",
            "last_synced_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "created_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
            "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
        }
        events.append(ev_row)
    else:
        # Upsert update
        existing["summary"] = summary.strip()
        existing["description"] = description
        existing["location"] = location
        existing["start_time"] = _iso(st)
        existing["end_time"] = _iso(en)
        existing["time_zone"] = timeZone.strip()
        existing["source"] = "created_via_api"
        if existing.get("status") not in ("confirmed", "cancelled", "tentative", "deleted_local"):
            existing["status"] = "confirmed"
        existing["last_synced_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        existing["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        ev_row = existing

    # Upsert attendees rows (dedupe per event, store lowercased)
    if norm_attendees:
        existing_for_event = {}
        for att in event_attendees:
            if att.get("event_id") == ev_row["id"] and isinstance(att.get("email"), str):
                existing_for_event[att["email"].strip().lower()] = att

        for em in norm_attendees:
            if em in existing_for_event:
                # touch updated_at
                existing_for_event[em]["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            else:
                # basic email length constraint
                if len(em) < 3 or len(em) > 320:
                    continue
                event_attendees.append({
                    "id": _new_att_id(),
                    "event_id": ev_row["id"],
                    "email": em,
                    "response_status": None,
                    "optional": False,
                    "created_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
                    "updated_at": _iso(datetime.datetime.now(datetime.timezone.utc)),
                })

    # Mark request succeeded
    if _transition_allowed(req_row["status"], "succeeded"):
        req_row["status"] = "succeeded"
        req_row["http_status"] = 200
        req_row["google_event_id"] = google_event_id
        req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        req_row["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))

    # Update connection last_used_at
    conn["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    conn["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    for i, c in enumerate(oauths):
        if c.get("id") == conn.get("id"):
            oauths[i] = conn
            break

    _save("events.json", events)
    _save("event_attendees.json", event_attendees)
    _save("api_requests.json", api_requests)
    _save("oauth_connections.json", oauths)

    return {
        "event": ev_row,
        "attendees": [a for a in event_attendees if a.get("event_id") == ev_row.get("id")],
        "latency_ms": int((time.time() - t0) * 1000),
    }

def whoami(accessToken, includeQuota=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0212000" if __import__("os").path.isdir("./environment_mix/0212000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _hash_token(tok):
        return hashlib.sha256(tok.encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # default includeQuota true
    if includeQuota is None:
        includeQuota = True
    if not isinstance(includeQuota, bool):
        includeQuota = True

    # Validate accessToken
    if not isinstance(accessToken, str) or not accessToken.strip():
        # whoami not part of api_requests.tool_name enum, so do not log to api_requests
        return _err("VALIDATION_ERROR", "accessToken must be a non-empty string", field="accessToken")

    access_token_hash = _hash_token(accessToken)

    oauth_connections = _load("oauth_connections.json")
    conn = None
    for c in oauth_connections:
        if c.get("provider") != "google":
            continue
        if c.get("id") == accessToken or c.get("access_token_hash") == access_token_hash:
            conn = c
            break

    if not conn:
        return _err("UNAUTHORIZED", "accessToken not associated with an OAuth connection")

    if conn.get("status") == "revoked":
        # Tool spec says FORBIDDEN but contract error codes do not include it; use UNAUTHORIZED-equivalent code
        return _err("UNAUTHORIZED", "OAuth connection is revoked", error_code="oauth_revoked")

    # Update last_used_at for observability
    now2 = datetime.datetime.now(datetime.timezone.utc)
    for c in oauth_connections:
        if c.get("id") == conn.get("id"):
            c["last_used_at"] = _iso(now2)
            c["updated_at"] = _iso(now2)
            break
    _save("oauth_connections.json", oauth_connections)

    quota = None
    if includeQuota:
        api_requests = _load("api_requests.json")
        window_start = now2 - datetime.timedelta(seconds=60)
        inflight = 0
        total_60s = 0
        for r in api_requests:
            if r.get("oauth_connection_id") != conn.get("id"):
                continue
            created_at = r.get("created_at")
            try:
                if isinstance(created_at, str):
                    x = created_at
                    if x.endswith("Z"):
                        x = x[:-1] + "+00:00"
                    dtc = datetime.datetime.fromisoformat(x)
                    if dtc.tzinfo is None:
                        dtc = dtc.replace(tzinfo=datetime.timezone.utc)
                    dtc = dtc.astimezone(datetime.timezone.utc)
                else:
                    continue
            except ValueError:
                continue
            if dtc >= window_start:
                total_60s += 1
                if r.get("status") in ("received", "validated", "calling_google"):
                    inflight += 1
        limit = 60
        quota = {
            "window_seconds": 60,
            "inflight_limit": limit,
            "inflight_used": inflight,
            "inflight_remaining": max(0, limit - inflight),
            "requests_last_60s": total_60s
        }

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "oauth_connection": {
            "id": conn.get("id"),
            "provider": conn.get("provider"),
            "google_user_id": conn.get("google_user_id"),
            "primary_calendar_id": conn.get("primary_calendar_id"),
            "status": conn.get("status"),
            "scopes": conn.get("scopes"),
            "token_expires_at": conn.get("token_expires_at"),
            "last_used_at": conn.get("last_used_at"),
            "created_at": conn.get("created_at"),
            "updated_at": conn.get("updated_at"),
        },
        "access_token_hash": access_token_hash,
        "quota": quota,
        "latency_ms": latency_ms
    }

def list_oauth_connections(accessToken, status=None, provider=None, pageSize=None, pageToken=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, hashlib, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0212000" if __import__("os").path.isdir("./environment_mix/0212000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    t0 = time.time()

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if not v:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _hash_token(tok):
        return hashlib.sha256(tok.encode("utf-8")).hexdigest()

    def _new_req_id():
        return f"gcal_req_{uuid.uuid4().hex}"

    def _find_conn(oauths, token):
        if not isinstance(token, str) or not token.strip():
            return None
        t = token.strip()
        for c in oauths:
            if c.get("id") == t:
                return c
        h = _hash_token(t)
        for c in oauths:
            if c.get("access_token_hash") == h:
                return c
        return None

    def _log(api_requests, oauth_connection_id, access_token_hash, status_val, http_status=None, error_code=None, error_message=None):
        row = {
            "id": _new_req_id(),
            "oauth_connection_id": oauth_connection_id,
            "tool_name": "list-events",  # schema enum doesn't include this tool; use closest read tool name.
            "access_token_hash": access_token_hash,
            "time_min": None,
            "time_max": None,
            "max_results": None,
            "google_event_id": None,
            "create_summary": None,
            "create_start_time": None,
            "create_end_time": None,
            "create_time_zone": None,
            "create_attendees": None,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "status": status_val,
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        api_requests.append(row)
        return row

    def _encode_token(payload):
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok.strip():
            return None
        pad = "=" * (-len(tok) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    oauths = _load("oauth_connections.json")
    api_requests = _load("api_requests.json")

    access_hash = _hash_token(accessToken) if isinstance(accessToken, str) else ""

    if not isinstance(accessToken, str) or not accessToken.strip():
        _log(api_requests, None, access_hash, "failed", http_status=400, error_code="validation_error", error_message="accessToken must be a non-empty string")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "accessToken must be a non-empty string", field="accessToken")

    # Validate enums
    if status is not None and status not in ("active", "revoked", "error"):
        _log(api_requests, None, access_hash, "failed", http_status=400, error_code="validation_error", error_message="Invalid status filter")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked, error", field="status")
    if provider is not None and provider != "google":
        _log(api_requests, None, access_hash, "failed", http_status=400, error_code="validation_error", error_message="Invalid provider filter")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "provider must be 'google'", field="provider")
    if sortBy is None:
        sortBy = "updated_at"
    if sortBy not in ("created_at", "updated_at", "last_used_at"):
        _log(api_requests, None, access_hash, "failed", http_status=400, error_code="validation_error", error_message="Invalid sortBy")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "sortBy must be one of: created_at, updated_at, last_used_at", field="sortBy")
    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        _log(api_requests, None, access_hash, "failed", http_status=400, error_code="validation_error", error_message="Invalid sortOrder")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc", field="sortOrder")
    if pageSize is None:
        pageSize = 50
    if isinstance(pageSize, bool) or not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _log(api_requests, None, access_hash, "failed", http_status=400, error_code="validation_error", error_message="Invalid pageSize")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "pageSize must be an integer in [1, 200]", field="pageSize")

    caller_conn = _find_conn(oauths, accessToken)
    if not caller_conn:
        _log(api_requests, None, access_hash, "failed", http_status=401, error_code="unauthorized", error_message="accessToken is invalid or not associated with a stored OAuth connection")
        _save("api_requests.json", api_requests)
        return _err("UNAUTHORIZED", "accessToken is invalid or not associated with a stored OAuth connection")

    # Scope: visible connections are those for the same google_user_id (typical)
    visible = [c for c in oauths if c.get("provider") == "google" and c.get("google_user_id") == caller_conn.get("google_user_id")]

    if provider is not None:
        visible = [c for c in visible if c.get("provider") == provider]
    if status is not None:
        visible = [c for c in visible if c.get("status") == status]

    reverse = (sortOrder == "desc")
    visible.sort(key=lambda r: (_parse_dt(r.get(sortBy)) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or ""), reverse=reverse)

    start = 0
    tok = _decode_token(pageToken)
    if tok and tok.get("sortBy") == sortBy and tok.get("sortOrder") == sortOrder:
        try:
            start = int(tok.get("offset", 0))
            if start < 0:
                start = 0
        except Exception:
            start = 0

    page = visible[start:start + pageSize]
    next_offset = start + len(page)
    next_token = _encode_token({"offset": next_offset, "sortBy": sortBy, "sortOrder": sortOrder}) if next_offset < len(visible) else None

    # update last_used on caller connection
    caller_conn["last_used_at"] = _iso(now)
    caller_conn["updated_at"] = _iso(now)
    _save("oauth_connections.json", oauths)

    _log(api_requests, caller_conn.get("id"), access_hash, "succeeded", http_status=200)
    _save("api_requests.json", api_requests)

    return {
        "oauthConnections": page,
        "total": len(visible),
        "pageSize": pageSize,
        "nextPageToken": next_token,
        "has_more": next_token is not None,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def update_oauth_connection_status(accessToken, oauthConnectionId, status, errorMessage=None, **_extra):
    import json, os, datetime, hashlib, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0212000" if __import__("os").path.isdir("./environment_mix/0212000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _hash_token(tok):
        return hashlib.sha256(tok.encode("utf-8")).hexdigest()

    def _new_req_id():
        return f"gcal_req_{uuid.uuid4().hex}"

    def _append_request(reqs, oauth_connection_id, access_token_hash, status_val, http_status=None, error_code=None, error_message=None):
        row = {
            "id": _new_req_id(),
            "oauth_connection_id": oauth_connection_id,
            "tool_name": "get-event",  # schema enum limitation for api_requests; keep valid
            "access_token_hash": access_token_hash,
            "time_min": None,
            "time_max": None,
            "max_results": None,
            "google_event_id": None,
            "create_summary": None,
            "create_start_time": None,
            "create_end_time": None,
            "create_time_zone": None,
            "create_attendees": None,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "status": status_val,
            "started_at": _iso(now),
            "finished_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        return row

    def _finish_request(row, status_val, http_status=None, error_code=None, error_message=None):
        row["status"] = status_val
        row["http_status"] = http_status if http_status is not None else row.get("http_status")
        row["error_code"] = error_code
        row["error_message"] = error_message
        row["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        row["updated_at"] = row["finished_at"]

    def _rate_limited(reqs, oauth_connection_id):
        window_start = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        count = 0
        for r in reqs:
            if r.get("oauth_connection_id") != oauth_connection_id:
                continue
            if r.get("status") not in ("received", "validated", "calling_google"):
                continue
            ts = r.get("created_at") or r.get("started_at")
            if not isinstance(ts, str):
                continue
            try:
                s = ts.strip()
                s = s[:-1] + "+00:00" if s.endswith("Z") else s
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            except ValueError:
                continue
            if dt >= window_start:
                count += 1
                if count >= 60:
                    return True
        return False

    # Validate inputs
    if not isinstance(accessToken, str) or not accessToken.strip():
        return _err("VALIDATION_ERROR", "accessToken must be a non-empty string", field="accessToken")
    if not isinstance(oauthConnectionId, str) or not oauthConnectionId.strip():
        return _err("VALIDATION_ERROR", "oauthConnectionId must be a non-empty string", field="oauthConnectionId")
    if status not in ("active", "revoked", "error"):
        return _err("VALIDATION_ERROR", "status must be one of: active, revoked, error", field="status")
    if errorMessage is not None and not isinstance(errorMessage, str):
        return _err("VALIDATION_ERROR", "errorMessage must be a string", field="errorMessage")

    oauths = _load("oauth_connections.json")
    reqs = _load("api_requests.json")

    access_hash = _hash_token(accessToken)

    # Authenticate: allow accessToken to be a connection id OR match access_token_hash
    caller_conn = None
    for c in oauths:
        if c.get("provider") != "google":
            continue
        if c.get("id") == accessToken or c.get("access_token_hash") == access_hash:
            caller_conn = c
            break

    if caller_conn is None:
        row = _append_request(reqs, None, access_hash, "received")
        _finish_request(row, "failed", http_status=401, error_code="unauthorized", error_message="Invalid accessToken")
        _save("api_requests.json", reqs)
        return _err("UNAUTHORIZED", "accessToken is invalid or not associated with a stored OAuth connection")

    # Log received for observable dynamics
    row = _append_request(reqs, caller_conn.get("id"), access_hash, "received")

    # Rate limiting
    if _rate_limited(reqs, caller_conn.get("id")):
        _finish_request(row, "failed", http_status=429, error_code="rate_limited", error_message="Rate limit exceeded")
        _save("api_requests.json", reqs)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="rate_limited")

    # Find target connection
    target = None
    for c in oauths:
        if c.get("id") == oauthConnectionId and c.get("provider") == "google":
            target = c
            break
    if target is None:
        _finish_request(row, "failed", http_status=404, error_code="not_found", error_message="OAuth connection not found")
        _save("api_requests.json", reqs)
        return _err("NOT_FOUND", "OAuth connection not found", oauthConnectionId=oauthConnectionId)

    # Lifecycle transitions for oauth_connections
    transitions = {
        "active": ["revoked", "error"],
        "error": ["active", "revoked"],
        "revoked": [],
    }
    old = target.get("status")
    new = status

    # Idempotent: setting to same state is a no-op but should succeed and persist updated_at/last_used_at
    if old == new:
        target["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        target["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        _save("oauth_connections.json", oauths)
        _finish_request(row, "succeeded", http_status=200)
        _save("api_requests.json", reqs)
        return {"oauth_connection": target, "idempotent": True, "latency_ms": int((time.time() - t0) * 1000)}

    allowed = transitions.get(old, [])
    if new not in allowed:
        _finish_request(row, "failed", http_status=409, error_code="invalid_transition", error_message=f"Invalid transition from {old} to {new}")
        _save("api_requests.json", reqs)
        return _err("INVALID_TRANSITION", f"Invalid transition from {old} to {new}", from_status=old, to_status=new)

    # Apply change
    target["status"] = new
    # store errorMessage only as a sanitized error_message in api_requests; schema has no place on oauth_connections
    target["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    target["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    _save("oauth_connections.json", oauths)

    _finish_request(row, "succeeded", http_status=200)
    _save("api_requests.json", reqs)

    resp = {"oauth_connection": target, "latency_ms": int((time.time() - t0) * 1000)}
    if errorMessage and new == "error":
        resp["note"] = errorMessage
    return resp

def update_event_status(accessToken, eventId, status, note=None, **_extra):
    import json, os, datetime, hashlib, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0212000" if __import__("os").path.isdir("./environment_mix/0212000") else "/app/database")
