    def _append_req(reqs, oauth_connection_id, access_token_hash, status_val, http_status=None, error_code=None, error_message=None, google_event_id=None):
        row = {
            "id": _new_req_id(),
            "oauth_connection_id": oauth_connection_id,
            "tool_name": "get-event",  # schema enum does not include update-event-status; use closest audited tool
            "access_token_hash": access_token_hash,
            "time_min": None,
            "time_max": None,
            "max_results": None,
            "google_event_id": google_event_id,
            "create_summary": None,
            "create_start_time": None,
            "create_end_time": None,
            "create_time_zone": None,
            "create_attendees": None,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "status": status_val,
            "started_at": _iso(now),
            "finished_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        return row

    def _finish_req(row, status_val, http_status=None, error_code=None, error_message=None):
        row["status"] = status_val
        if http_status is not None:
            row["http_status"] = http_status
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        row["finished_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        row["updated_at"] = row["finished_at"]

    # ---- Validate inputs
    if not isinstance(accessToken, str) or not accessToken.strip():
        reqs = _load("api_requests.json")
        row = _append_req(reqs, None, _hash_token(accessToken) if isinstance(accessToken, str) else "sha256:", "failed",
                          http_status=400, error_code="validation_error", error_message="accessToken must be a non-empty string")
        _finish_req(row, "failed", http_status=400, error_code="validation_error", error_message="accessToken must be a non-empty string")
        _save("api_requests.json", reqs)
        return _err("VALIDATION_ERROR", "accessToken must be a non-empty string", field="accessToken")

    if not isinstance(eventId, str) or not eventId.strip():
        reqs = _load("api_requests.json")
        row = _append_req(reqs, None, _hash_token(accessToken), "failed",
                          http_status=400, error_code="validation_error", error_message="eventId must be a non-empty string")
        _finish_req(row, "failed", http_status=400, error_code="validation_error", error_message="eventId must be a non-empty string")
        _save("api_requests.json", reqs)
        return _err("VALIDATION_ERROR", "eventId must be a non-empty string", field="eventId")

    allowed_status = ("confirmed", "cancelled", "tentative", "deleted_local")
    if status not in allowed_status:
        reqs = _load("api_requests.json")
        row = _append_req(reqs, None, _hash_token(accessToken), "failed",
                          http_status=400, error_code="validation_error", error_message="Invalid status")
        _finish_req(row, "failed", http_status=400, error_code="validation_error", error_message="Invalid status")
        _save("api_requests.json", reqs)
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=list(allowed_status))

    if note is not None and not isinstance(note, str):
        reqs = _load("api_requests.json")
        row = _append_req(reqs, None, _hash_token(accessToken), "failed",
                          http_status=400, error_code="validation_error", error_message="note must be a string")
        _finish_req(row, "failed", http_status=400, error_code="validation_error", error_message="note must be a string")
        _save("api_requests.json", reqs)
        return _err("VALIDATION_ERROR", "note must be a string", field="note")

    access_hash = _hash_token(accessToken)

    oauths = _load("oauth_connections.json")
    events = _load("events.json")
    reqs = _load("api_requests.json")

    # Resolve oauth connection without impossible token-hash matching: accept id-style token or ambient
    conn = None
    for c in oauths:
        if c.get("provider") == "google" and (c.get("id") == accessToken or c.get("access_token_hash") == accessToken):
            conn = c
            break
    if conn is None:
        for c in oauths:
            if c.get("provider") == "google" and c.get("status") in ("active", "error"):
                conn = c
                break

    req_row = _append_req(reqs, conn.get("id") if conn else None, access_hash, "received")

    if conn is None:
        _finish_req(req_row, "failed", http_status=401, error_code="unauthorized", error_message="No usable OAuth connection found")
        _save("api_requests.json", reqs)
        return _err("UNAUTHORIZED", "Invalid accessToken or no usable OAuth connection")

    if conn.get("status") == "revoked":
        _finish_req(req_row, "failed", http_status=401, error_code="oauth_revoked", error_message="OAuth connection is revoked")
        _save("api_requests.json", reqs)
        return _err("UNAUTHORIZED", "OAuth connection is revoked", error_code="oauth_revoked", oauthConnectionId=conn.get("id"))

    # Rate limit
    window_start = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)

    def _parse_req_time(s):
        if not isinstance(s, str) or not s:
            return None
        t = s[:-1] + "+00:00" if s.endswith("Z") else s
        try:
            dt = datetime.datetime.fromisoformat(t)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    inflight = 0
    for r in reqs:
        if r.get("oauth_connection_id") != conn.get("id"):
            continue
        if r.get("status") not in ("received", "validated", "calling_google"):
            continue
        st = _parse_req_time(r.get("started_at"))
        if st is not None and st >= window_start:
            inflight += 1
    if inflight > 60:
        _finish_req(req_row, "failed", http_status=429, error_code="rate_limited", error_message="Rate limit exceeded")
        _save("api_requests.json", reqs)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="rate_limited")

    req_row["status"] = "validated"
    req_row["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))

    # Find event: treat eventId as local id primarily; if not found, accept google_event_id fallback (audit showed mismatched ids)
    ev = None
    for e in events:
        if e.get("id") == eventId:
            ev = e
            break
    if ev is None:
        # fallback: if caller passed a connection-like id, attempt to resolve by google_event_id within this connection
        for e in events:
            if e.get("oauth_connection_id") == conn.get("id") and e.get("google_event_id") == eventId:
                ev = e
                break

    if ev is None:
        _finish_req(req_row, "failed", http_status=404, error_code="not_found", error_message="Event not found")
        _save("api_requests.json", reqs)
        return _err("NOT_FOUND", "Event not found", eventId=eventId)

    # Enforce lifecycle transitions
    transitions = {
        "tentative": {"confirmed", "cancelled", "deleted_local"},
        "confirmed": {"cancelled", "deleted_local"},
        "cancelled": {"deleted_local"},
        "deleted_local": set(),
    }
    cur = ev.get("status")
    if cur not in transitions:
        _finish_req(req_row, "failed", http_status=409, error_code="invalid_transition", error_message="Current event status is invalid")
        _save("api_requests.json", reqs)
        return _err("INVALID_TRANSITION", "Current event status is invalid", current=cur, requested=status)

    if status == cur:
        # Idempotent: still record succeeded without changing row materially
        conn["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
        conn["updated_at"] = conn["last_used_at"]
        _save("oauth_connections.json", oauths)
        _finish_req(req_row, "succeeded", http_status=200)
        _save("api_requests.json", reqs)
        return {"event": ev, "note": note, "latency_ms": int((time.time() - t0) * 1000)}

    if status not in transitions[cur]:
        _finish_req(req_row, "failed", http_status=409, error_code="invalid_transition", error_message="Requested status transition is not permitted")
        _save("api_requests.json", reqs)
        return _err(
            "INVALID_TRANSITION",
            "Requested status transition is not permitted by lifecycle rules",
            current=cur,
            requested=status,
            allowed=sorted(list(transitions[cur])),
        )

    # Mutate and persist
    ev["status"] = status
    ev["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    # do not add new fields not in schema; note is only returned (audit note is external)

    _save("events.json", events)

    conn["last_used_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
    conn["updated_at"] = conn["last_used_at"]
    _save("oauth_connections.json", oauths)

    _finish_req(req_row, "succeeded", http_status=200)
    _save("api_requests.json", reqs)

    return {"event": ev, "note": note, "latency_ms": int((time.time() - t0) * 1000)}

def list_api_requests(accessToken, toolName=None, status=None, startedAfter=None, startedBefore=None, pageSize=None, pageToken=None, **_extra):
    import json, os, datetime, hashlib, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0212000" if __import__("os").path.isdir("./environment_mix/0212000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    t0 = time.time()

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_iso(s, field):
        if s is None:
            return (None, None)
        if not isinstance(s, str) or not s.strip():
            return (None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO datetime string", field=field))
        try:
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (dt.astimezone(datetime.timezone.utc), None)
        except ValueError:
            return (None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO datetime string", field=field))

    def _hash_token(tok):
        return hashlib.sha256(tok.encode("utf-8")).hexdigest()

    def _new_req_id():
        return f"gcal_req_{uuid.uuid4().hex}"

    def _find_conn(oauths, token):
        if not isinstance(token, str) or not token.strip():
            return None
        t = token.strip()
        for c in oauths:
            if c.get("id") == t:
                return c
        h = _hash_token(t)
        for c in oauths:
            if c.get("access_token_hash") == h:
                return c
        return None

    def _encode_token(payload):
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok.strip():
            return None
        pad = "=" * (-len(tok) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _log_call(api_requests, oauth_connection_id, access_token_hash, status_val, http_status=None, error_code=None, error_message=None):
        row = {
            "id": _new_req_id(),
            "oauth_connection_id": oauth_connection_id,
            "tool_name": "list-events",  # schema enum doesn't include list-api-requests tool; record as allowed tool.
            "access_token_hash": access_token_hash,
            "time_min": None,
            "time_max": None,
            "max_results": None,
            "google_event_id": None,
            "create_summary": None,
            "create_start_time": None,
            "create_end_time": None,
            "create_time_zone": None,
            "create_attendees": None,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "status": status_val,
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        api_requests.append(row)
        return row

    oauths = _load("oauth_connections.json")
    api_requests = _load("api_requests.json")

    access_hash = _hash_token(accessToken) if isinstance(accessToken, str) else ""

    if not isinstance(accessToken, str) or not accessToken.strip():
        _log_call(api_requests, None, access_hash, "failed", http_status=400, error_code="validation_error", error_message="accessToken must be a non-empty string")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "accessToken must be a non-empty string", field="accessToken")

    conn = _find_conn(oauths, accessToken)
    if not conn:
        _log_call(api_requests, None, access_hash, "failed", http_status=401, error_code="unauthorized", error_message="accessToken is invalid or not associated with a stored OAuth connection")
        _save("api_requests.json", api_requests)
        return _err("UNAUTHORIZED", "accessToken is invalid or not associated with a stored OAuth connection")

    # Validate filters
    allowed_tool = {"list-events", "get-event", "create-event", "whoami", "list-oauth-connections", "update-oauth-connection-status", "update-event-status", "list-api-requests"}
    if toolName is not None and toolName not in allowed_tool:
        _log_call(api_requests, conn.get("id"), access_hash, "failed", http_status=400, error_code="validation_error", error_message="Invalid toolName")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "toolName is invalid", field="toolName", allowed=sorted(allowed_tool))
    if status is not None and status not in ("received", "validated", "calling_google", "succeeded", "failed"):
        _log_call(api_requests, conn.get("id"), access_hash, "failed", http_status=400, error_code="validation_error", error_message="Invalid status")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "status is invalid", field="status")

    sa_dt, e1 = _parse_iso(startedAfter, "startedAfter")
    if e1:
        _log_call(api_requests, conn.get("id"), access_hash, "failed", http_status=400, error_code="validation_error", error_message=e1["error"]["message"])
        _save("api_requests.json", api_requests)
        return e1
    sb_dt, e2 = _parse_iso(startedBefore, "startedBefore")
    if e2:
        _log_call(api_requests, conn.get("id"), access_hash, "failed", http_status=400, error_code="validation_error", error_message=e2["error"]["message"])
        _save("api_requests.json", api_requests)
        return e2

    if pageSize is None:
        pageSize = 50
    if isinstance(pageSize, bool) or not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        _log_call(api_requests, conn.get("id"), access_hash, "failed", http_status=400, error_code="validation_error", error_message="Invalid pageSize")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "pageSize must be an integer in [1, 200]", field="pageSize")

    # Rate limit enforcement still applies to this call too
    window_start = now - datetime.timedelta(seconds=60)
    inflight = 0
    for r in api_requests:
        if r.get("oauth_connection_id") != conn.get("id"):
            continue
        if r.get("status") not in ("received", "validated", "calling_google"):
            continue
        s = r.get("started_at") or r.get("created_at")
        try:
            if isinstance(s, str):
                x = s[:-1] + "+00:00" if s.endswith("Z") else s
                dt = datetime.datetime.fromisoformat(x)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            else:
                continue
        except Exception:
            continue
        if dt >= window_start:
            inflight += 1
    if inflight > 60:
        _log_call(api_requests, conn.get("id"), access_hash, "failed", http_status=429, error_code="rate_limited", error_message="Rate limit exceeded")
        _save("api_requests.json", api_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded", error_code="rate_limited")

    # Filter request logs by connection
    rows = [r for r in api_requests if r.get("oauth_connection_id") == conn.get("id")]

    if toolName is not None:
        rows = [r for r in rows if r.get("tool_name") == toolName]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    def _row_started_at(r):
        v = r.get("started_at") or r.get("created_at")
        if not isinstance(v, str):
            return None
        try:
            x = v[:-1] + "+00:00" if v.endswith("Z") else v
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    if sa_dt is not None:
        rows = [r for r in rows if (_row_started_at(r) is not None and _row_started_at(r) >= sa_dt)]
    if sb_dt is not None:
        rows = [r for r in rows if (_row_started_at(r) is not None and _row_started_at(r) <= sb_dt)]

    rows.sort(key=lambda r: (_row_started_at(r) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or ""), reverse=True)

    start = 0
    tok = _decode_token(pageToken)
    if tok:
        try:
            start = int(tok.get("offset", 0))
            if start < 0:
                start = 0
        except Exception:
            start = 0

    page = rows[start:start + pageSize]
    next_offset = start + len(page)
    next_token = _encode_token({"offset": next_offset}) if next_offset < len(rows) else None

    conn["last_used_at"] = _iso(now)
    conn["updated_at"] = _iso(now)
    _save("oauth_connections.json", oauths)

    _log_call(api_requests, conn.get("id"), access_hash, "succeeded", http_status=200)
    _save("api_requests.json", api_requests)

    return {
        "requests": page,
        "total": len(rows),
        "pageSize": pageSize,
        "nextPageToken": next_token,
        "has_more": next_token is not None,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_oauth_connection(accessToken, oauthConnectionId, **_extra):
    import json, os, datetime, hashlib, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0212000" if __import__("os").path.isdir("./environment_mix/0212000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    t0 = time.time()

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _hash_token(tok):
        return hashlib.sha256(tok.encode("utf-8")).hexdigest()

    def _new_req_id():
        return f"gcal_req_{uuid.uuid4().hex}"

    def _find_conn(oauths, token):
        if not isinstance(token, str) or not token.strip():
            return None
        t = token.strip()
        for c in oauths:
            if c.get("id") == t:
                return c
        h = _hash_token(t)
        for c in oauths:
            if c.get("access_token_hash") == h:
                return c
        return None

    def _log(api_requests, oauth_connection_id, access_token_hash, status_val, http_status=None, error_code=None, error_message=None):
        row = {
            "id": _new_req_id(),
            "oauth_connection_id": oauth_connection_id,
            "tool_name": "get-event",  # schema enum doesn't include this tool; record as allowed tool.
            "access_token_hash": access_token_hash,
            "time_min": None,
            "time_max": None,
            "max_results": None,
            "google_event_id": None,
            "create_summary": None,
            "create_start_time": None,
            "create_end_time": None,
            "create_time_zone": None,
            "create_attendees": None,
            "http_status": http_status,
            "error_code": error_code,
            "error_message": error_message,
            "status": status_val,
            "started_at": _iso(now),
            "finished_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        api_requests.append(row)
        return row

    oauths = _load("oauth_connections.json")
    api_requests = _load("api_requests.json")

    access_hash = _hash_token(accessToken) if isinstance(accessToken, str) else ""

    if not isinstance(accessToken, str) or not accessToken.strip():
        _log(api_requests, None, access_hash, "failed", http_status=400, error_code="validation_error", error_message="accessToken must be a non-empty string")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "accessToken must be a non-empty string", field="accessToken")
    if not isinstance(oauthConnectionId, str) or not oauthConnectionId.strip():
        _log(api_requests, None, access_hash, "failed", http_status=400, error_code="validation_error", error_message="oauthConnectionId must be a non-empty string")
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "oauthConnectionId must be a non-empty string", field="oauthConnectionId")

    caller_conn = _find_conn(oauths, accessToken)
    if not caller_conn:
        _log(api_requests, None, access_hash, "failed", http_status=401, error_code="unauthorized", error_message="accessToken is invalid or not associated with a stored OAuth connection")
        _save("api_requests.json", api_requests)
        return _err("UNAUTHORIZED", "accessToken is invalid or not associated with a stored OAuth connection")

    target = None
    for c in oauths:
        if c.get("id") == oauthConnectionId:
            target = c
            break
    if not target:
        _log(api_requests, caller_conn.get("id"), access_hash, "failed", http_status=404, error_code="not_found", error_message="OAuth connection not found")
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "OAuth connection not found", oauthConnectionId=oauthConnectionId)

    if target.get("google_user_id") != caller_conn.get("google_user_id"):
        _log(api_requests, caller_conn.get("id"), access_hash, "failed", http_status=401, error_code="unauthorized", error_message="Not authorized for this OAuth connection")
        _save("api_requests.json", api_requests)
        return _err("UNAUTHORIZED", "Not authorized for this OAuth connection")

    # Update caller last_used
    caller_conn["last_used_at"] = _iso(now)
    caller_conn["updated_at"] = _iso(now)
    _save("oauth_connections.json", oauths)

    _log(api_requests, caller_conn.get("id"), access_hash, "succeeded", http_status=200)
    _save("api_requests.json", api_requests)

    # Never return raw tokens: store has only hashes/ciphertext; return row as-is.
    return {"oauthConnection": target, "latency_ms": int((time.time() - t0) * 1000)}
